-- Page id=29 ("Loading — Mark In Progress", GatePass entity): ship a new
-- page_version row (never editing the V165 one in place), same pattern as
-- V165 itself.
--
-- 1. Fixes the SKU grid + both KPIs' 500 error: they filtered
--    OrderDispatchDetail on gate_pass_id, a column that does not exist on
--    m5_order_dispatch_detail (confirmed by DESCRIBE). The linkage the form
--    already captures is route_id (onChangeFill from the Gate Pass picker) --
--    switched both KPIs and the ListView to filter on that instead.
-- 2. Adds a barcode / offer-variant picker to the Order / SKU Line Items
--    section (SkuMaster already allows several rows to share one barcode,
--    one per offer_variant -- this lets the operator pick the applicable one
--    when that happens; onChangeFill resolves sku_code/bundle_pieces).
-- 3. Adds a "Without Order Sheet Vehicle Loading" section: pick the
--    PackingRun this vehicle's conveyor-scanned bundles came from (plain
--    in-form selection, nothing persisted -- same pattern as the existing
--    Route/Gate Pass pickers), a live Bundle Count KPI (PackingScanLog rows
--    accepted for that run), and a Total Quantity KPI that joins SkuMaster
--    to pull bundle_pieces per row so the sum equals bundle_count x
--    pieces_per_bundle, computed by the query rather than typed by hand.
-- 4. Adds a read-only "Loading Timeline" grid (LoadingProgressDetail,
--    filtered to this instance) showing gate pass/vehicle/route/supervisor
--    plus the new loading_start_time/loading_finish_time columns from
--    V182 (stamped by WorkflowProjectionListener's new state_ts_columns_json
--    support) and supervisor_name (mirrored via the existing field_map_json
--    mechanism, also extended in V182).
--
-- Version number is computed from the existing max (not hardcoded) so this
-- is safe to run regardless of how many versions page 29 already has.
-- Guarded on body_json so re-running this file is a no-op if it already ran.
INSERT INTO page_version (page_id, version, status, body_json, published_at)
SELECT 29,
       (SELECT COALESCE(MAX(version), 0) + 1 FROM page_version WHERE page_id = 29),
       'PUBLISHED',
       '{"kind":"layout","schemaVersion":2,"entity":"GatePass","layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"Loading — Mark In Progress","span":12,"subtitle":"Vehicles that have taken their first weight and are ready to load. Pick the gate pass (scan / pick / type), select a route, then Start Loading.","children":[{"kind":"Form","bindings":{"fields":[{"name":"gpNumber","label":"Gate Pass # (scan / pick / type)","type":"select","required":true,"freeSolo":true,"scannable":true,"optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"LoadingSupervisor"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","gp_number"],"sort":[{"field":"gp_number","dir":"desc"}]},"valueField":"gp_number","labelField":"gp_number"},"onChangeFill":{"vehicle_no":"vehicle_no","instanceId":"workflow_instance_id","route_id":"route_id","supervisor_name":"supervisor_name"}},{"name":"vehicle_no","label":"Vehicle","type":"text","readOnly":true},{"name":"route_id","label":"Route","type":"select","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"OrderDispatchDetail","select":["route_id"],"distinct":true},"valueField":"route_id","labelField":"route_id"}}]}},{"kind":"Stack","direction":"row","gap":12,"children":[{"kind":"WorkflowActionButton","label":"▶ Start Loading","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"LOADING_IN_PROGRESS","color":"primary","visibleWhen":{"field":"form.route_id","op":"isNotEmpty"}},{"kind":"WorkflowActionButton","label":"📦 View Order","action":"page.open","page":"aria:loading-order","color":"secondary","args":{"params":{"route":"{{form.route_id}}"}}}]}]},{"kind":"Section","title":"Supervisor Status","span":12,"children":[{"kind":"Stack","direction":"row","gap":16,"children":[{"kind":"FormField","name":"supervisor_name","label":"Supervisor","type":"text","readOnly":true},{"kind":"KPI","label":"Loaded Qty (live)","unit":"units","live":true,"dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"route_id","op":"eq","value":"{{form.route_id}}"},"aggregate":{"field":"loading_qty","fn":"sum"},"recalcOn":["listview.loading_qty.change"]}},{"kind":"KPI","label":"Order Qty","unit":"units","dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"route_id","op":"eq","value":"{{form.route_id}}"},"aggregate":{"field":"order_qty","fn":"sum"}}}]},{"kind":"ListView","title":"Loading Timeline","dataSource":{"type":"entity","entity":"LoadingProgressDetail","filter":{"field":"workflow_instance_id","op":"eq","value":"{{form.instanceId}}"}},"columns":[{"field":"gate_pass_no","label":"Gate Pass #"},{"field":"vehicle_no","label":"Vehicle"},{"field":"route_id","label":"Route"},{"field":"supervisor_name","label":"Supervisor"},{"field":"loading_start_time","label":"Loading Start Time","render":"datetime"},{"field":"loading_finish_time","label":"Loading Finish Time","render":"datetime"}],"pageSize":5}]},{"kind":"Section","title":"Order / SKU Line Items","span":12,"children":[{"kind":"Form","bindings":{"fields":[{"name":"scanned_barcode","label":"Scan Barcode","type":"text","scannable":true},{"name":"offer_variant","label":"Offer / Variant (multiple offer stock for this barcode)","type":"select","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"SkuMaster","filter":{"field":"barcode","op":"eq","value":"{{form.scanned_barcode}}"},"select":["sku_code","offer_variant","bundle_pieces"]},"valueField":"offer_variant","labelField":"offer_variant"},"onChangeFill":{"sku_code":"sku_code","bundle_pieces":"bundle_pieces"}},{"name":"sku_code","label":"Resolved SKU","type":"text","readOnly":true},{"name":"bundle_pieces","label":"Pieces per Bundle","type":"number","readOnly":true}]}},{"kind":"ListView","dataSource":{"type":"entity","entity":"OrderDispatchDetail","filter":{"field":"route_id","op":"eq","value":"{{form.route_id}}"}},"selection":{"mode":"single","field":"selected","showCheckbox":true,"disableOthersOnSelect":true},"columns":[{"field":"sku_code","label":"SKU"},{"field":"description","label":"Description"},{"field":"loading_location","label":"Loading Location","widget_kind":"select","editable":true},{"field":"order_qty","label":"Order Qty","render":"number"},{"field":"loading_qty","label":"Loading Qty","render":"number","widget_kind":"number","editable":true,"onChange":{"recalc":["balance_qty","kpi.Loaded Qty (live)"]}},{"field":"balance_qty","label":"Balance Qty","render":"number"},{"field":"status","label":"Status","render":"badge","colorMap":{"LOADING_IN_PROGRESS":"green","PENDING":"orange","COMPLETED":"blue","SKIPPED":"red"}}],"rowActions":[{"label":"Stop Loading","action":"entity.update-field","args":{"field":"status","value":"PENDING"},"color":"error"},{"label":"Add Entry","action":"page.open","page":"aria:loading-add-entry","args":{"params":{"orderDispatchId":"{{row.id}}","skuCode":"{{row.sku_code}}"}},"color":"primary"}],"pageSize":25}]},{"kind":"Section","title":"Without Order Sheet Vehicle Loading","span":12,"subtitle":"For vehicles loaded straight off the conveyor packing line, without a dispatch order sheet. Pick the packing run whose bundles are loading onto this vehicle.","children":[{"kind":"Form","bindings":{"fields":[{"name":"packing_run_id","label":"Packing Run #","type":"select","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"PackingRun","filter":{"field":"status","op":"in","value":["RUNNING","PACKED"]},"select":["id","pr_number"]},"valueField":"id","labelField":"pr_number"}}]}},{"kind":"Stack","direction":"row","gap":16,"children":[{"kind":"FormField","name":"bundle_pieces","label":"Pieces per Bundle","type":"number","readOnly":true},{"kind":"KPI","label":"Bundle Count","unit":"bundles","live":true,"dataSource":{"type":"entity","entity":"PackingScanLog","filter":{"and":[{"field":"packing_run_id","op":"eq","value":"{{form.packing_run_id}}"},{"field":"outcome","op":"eq","value":"ACCEPTED"}]},"select":["id"],"aggregate":{"field":"id","fn":"count"}}},{"kind":"KPI","label":"Total Quantity","unit":"pcs","live":true,"dataSource":{"type":"entity","entity":"PackingScanLog","joins":[{"entity":"SkuMaster","as":"sm","on":"m5_packing_scan_log.sku_code = sm.sku_code"}],"filter":{"and":[{"field":"packing_run_id","op":"eq","value":"{{form.packing_run_id}}"},{"field":"outcome","op":"eq","value":"ACCEPTED"}]},"select":["sm.bundle_pieces as bundle_pieces"],"aggregate":{"field":"bundle_pieces","fn":"sum"}}}]}]},{"kind":"Section","span":12,"children":[{"kind":"Stack","direction":"row","gap":12,"justify":"flex-end","children":[{"kind":"WorkflowActionButton","label":"✓ Completed","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"LOADING_COMPLETED","color":"success"}]}]}]}]}',
       NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM page_version
  WHERE page_id = 29
    AND body_json = '{"kind":"layout","schemaVersion":2,"entity":"GatePass","layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"Loading — Mark In Progress","span":12,"subtitle":"Vehicles that have taken their first weight and are ready to load. Pick the gate pass (scan / pick / type), select a route, then Start Loading.","children":[{"kind":"Form","bindings":{"fields":[{"name":"gpNumber","label":"Gate Pass # (scan / pick / type)","type":"select","required":true,"freeSolo":true,"scannable":true,"optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"LoadingSupervisor"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","gp_number"],"sort":[{"field":"gp_number","dir":"desc"}]},"valueField":"gp_number","labelField":"gp_number"},"onChangeFill":{"vehicle_no":"vehicle_no","instanceId":"workflow_instance_id","route_id":"route_id","supervisor_name":"supervisor_name"}},{"name":"vehicle_no","label":"Vehicle","type":"text","readOnly":true},{"name":"route_id","label":"Route","type":"select","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"OrderDispatchDetail","select":["route_id"],"distinct":true},"valueField":"route_id","labelField":"route_id"}}]}},{"kind":"Stack","direction":"row","gap":12,"children":[{"kind":"WorkflowActionButton","label":"▶ Start Loading","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"LOADING_IN_PROGRESS","color":"primary","visibleWhen":{"field":"form.route_id","op":"isNotEmpty"}},{"kind":"WorkflowActionButton","label":"📦 View Order","action":"page.open","page":"aria:loading-order","color":"secondary","args":{"params":{"route":"{{form.route_id}}"}}}]}]},{"kind":"Section","title":"Supervisor Status","span":12,"children":[{"kind":"Stack","direction":"row","gap":16,"children":[